// Adds the AI judge's flag to the code-check result. The flag never changes "passed":
// it only marks replies a person should read (claims the reference does not support).
const chk = $('Check').first().json;
const j = $input.first().json || {};
const o = j.output && typeof j.output === 'object' ? j.output : null;
const claims = o && Array.isArray(o.claims) ? o.claims.filter(Boolean) : [];
const { judge_message, judge_reference, judge_team_status, ...row } = chk;
return [{
  json: {
    ...row,
    judge_flag: !chk.reply ? '-' : (o ? (o.unsupported === true ? 'yes' : 'no') : 'error'),
    judge_note: claims.join('; ').slice(0, 500),
  },
}];

